const onGfxCoreDropdownInit: OptionInitHandler<DropdownInfo> = (optionInfo) => {
	if (!Options.supportsGraphicOptions) {
		// No user-configurable options on this platform, shouldn't be possible to get here
		return;
	}

	switch (optionInfo.id) {
		case "option-gfx-profile":
			graphicsProfileSetter = () => {
				if (!optionInfo.dropdownItems) return;

				for (let i = 0; i < optionInfo.dropdownItems.length; i++) {
					const item = optionInfo.dropdownItems[i] as GraphicsProfileDropdownItem;
					if (item.profile == Options.graphicsOptions.profile) {
						optionInfo.selectedItemIndex = i;
						break;
					}
				}

				if (optionInfo.forceRender) {
					optionInfo.forceRender();
				}
			};
			graphicsProfileSetter();
			break;

		case "option-gfx-gpu":
			optionInfo.selectedItemIndex =
				optionInfo.dropdownItems?.findIndex(
					({ deviceID }: GPUDropdownItem) => deviceID === Options.graphicsOptions.deviceID,
				) ?? 0;
			break;

		case "option-gfx-window":
			optionInfo.selectedItemIndex =
				optionInfo.dropdownItems?.findIndex(
					({ fullscreen }: WindowModeDropdownItem) => fullscreen === Options.graphicsOptions.fullscreen,
				) ?? 0;
			break;

		case "option-gfx-res":
			optionInfo.selectedItemIndex = 0; // select "Auto" if we don't match a setting)
			if (Options.graphicsOptions.resolution.i != 0 && Options.graphicsOptions.resolution.j != 0) {
				// TODO findindex for current resolution
				for (let i = 0; i < Options.supportedOptions.resolutions.length; i++) {
					const width = Options.supportedOptions.resolutions[i].i;
					const height = Options.supportedOptions.resolutions[i].j;
					if (
						width === Options.graphicsOptions.resolution.i &&
						height === Options.graphicsOptions.resolution.j
					) {
						optionInfo.selectedItemIndex = i + 1; // +1 because the first item is Auto in the dropdown, but doesn't exist in displayModes
						break;
					}
				}
			}
			break;

		case "option-gfx-upscale-aa":
			const upscaleAASetter = () => {
				if (!optionInfo.dropdownItems) {
					return;
				}
				const autoItem = upscaleItemList.find((item) => item.mode == Options.graphicsOptions.autoUpscaleAA);
				if (autoItem) {
					optionInfo.dropdownItems[0].label =
						Locale.compose("LOC_OPTIONS_GFX_AUTO") + " - " + Locale.compose(autoItem.label);
				}
				if (optionInfo.forceRender) {
					optionInfo.forceRender();
				}
				optionInfo.selectedItemIndex =
					optionInfo.dropdownItems.findIndex(({ mode }: UpscalingAADropdownItem) => {
						return mode === Options.graphicsOptions.upscaleAA;
					}) ?? 0;
			};
			addGraphicsOptionSetter(optionInfo, upscaleAASetter);
			upscaleAASetter();
			optionInfo.selectedItemIndex =
				optionInfo.dropdownItems?.findIndex(
					({ mode }: UpscalingAADropdownItem) => mode === Options.graphicsOptions.upscaleAA,
				) ?? 0;
			updateAntialiasingVisiblity();
			break;
	}
};

const onGfxCoreDropdownUpdate: OptionUpdateHandler<DropdownInfo> = ({ id, dropdownItems = [] }, value) => {
	switch (id) {
		case "option-gfx-profile": {
			const { profile } = dropdownItems[value] as GraphicsProfileDropdownItem;
			Options.graphicsOptions.profile = profile;
			onGraphicsProfileChanged();
			break;
		}
		case "option-gfx-gpu": {
			// Note: may want a popup to reset to defaults, since they can vary for different hardware
			const { deviceID } = dropdownItems[value] as GPUDropdownItem;
			Options.graphicsOptions.deviceID = deviceID;
			break;
		}
		case "option-gfx-window": {
			const { fullscreen } = dropdownItems[value] as WindowModeDropdownItem;
			Options.graphicsOptions.fullscreen = fullscreen;
			break;
		}
		case "option-gfx-res": {
			const { resolution } = dropdownItems[value] as ResolutionDropdownItem;
			if (
				resolution.i != Options.graphicsOptions.resolution.i ||
				resolution.j != Options.graphicsOptions.resolution.j
			) {
				Options.needReloadRefCount += 1;
			}
			Options.graphicsOptions.resolution.i = resolution.i;
			Options.graphicsOptions.resolution.j = resolution.j;

			// We need to also adjust the font-scale if resolution drops below a threshold.
			if (!allowExtraLargeFonts(resolution.j)) {
				const scale = Configuration.getUser().uiFontScale;
				if (scale == FontScale.XLarge) {
					Configuration.getUser().setUiFontScale(FontScale.Large);
				}
			}
			break;
		}
		case "option-gfx-upscale-aa": {
			const { mode } = dropdownItems[value] as UpscalingAADropdownItem;
			Options.graphicsOptions.upscaleAA = mode;
			updateAntialiasingVisiblity();
			break;
		}
	}
};

